export enum DataType {
  ELECTRICITY = 'Electricity',
  FUEL_DIESEL = 'Fuel (Diesel)',
  FUEL_PETROL = 'Fuel (Petrol)',
  TRANSPORT = 'Transport'
}

export interface RequestMetadata {
  id: string;
  buyerCompanyName: string;
  dataType: DataType | 'ANY';
  reportingPeriod: string;
  createdAt: number;
}

export interface ExtractionResult {
  value: number | null;
  unit: string | null;
  detectedDataType: DataType | null;
  supplierName?: string;
  amountPayable?: number;
  billingPeriod?: string;
  currency?: string;
  confidence: number;
  reasoning?: string;
}

export interface SubmissionData {
  id: string;
  requestId: string;
  buyerName: string;
  activityValue: number;
  unit: string;
  dataType: DataType;
  emissionsKgCO2e: number;
  emissionFactor: number;
  notes?: string;
  timestamp: number;
  fileName?: string;
}

export const EMISSION_FACTORS: Record<DataType, number> = {
  [DataType.ELECTRICITY]: 0.50,   // kgCO2e per kWh
  [DataType.FUEL_DIESEL]: 2.68,    // kgCO2e per liter
  [DataType.FUEL_PETROL]: 2.31,    // kgCO2e per liter
  [DataType.TRANSPORT]: 0.21,      // kgCO2e per km
};

export const DATA_UNITS: Record<DataType, string> = {
  [DataType.ELECTRICITY]: 'kWh',
  [DataType.FUEL_DIESEL]: 'liters',
  [DataType.FUEL_PETROL]: 'liters',
  [DataType.TRANSPORT]: 'km'
};

import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  const prompt = `
    ROLE: You are an AI engine specialized in sustainability document understanding and emissions data extraction.
    TASK: Read the provided document (Electricity bill, Fuel receipt, or Transport invoice).

    EXTRACTION RULES:
    1. Identify Document Type: One of [Electricity, Fuel (Diesel), Fuel (Petrol), Transport]. 
       - Look for keywords like "kWh" for Electricity.
       - Look for "Diesel" vs "Petrol" for Fuel.
       - Look for "km", "distance", or "odometer" for Transport.
    2. Extract Activity Data:
       - Electricity: Total kWh.
       - Fuel: Total volume in liters.
       - Transport: Total distance in km.
    3. Extract Metadata: Supplier Name, Billing Period, Amount Payable, and Currency.

    CRITICAL: 
    - Set missing values to null. 
    - DO NOT hallucinate numbers.
    - Confidence is a score from 0 to 1 based on how clearly you can read the primary activity value.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: "image/jpeg", data: base64Image } }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          value: { type: Type.NUMBER, nullable: true },
          unit: { type: Type.STRING, nullable: true },
          detectedDataType: { 
            type: Type.STRING, 
            enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
          },
          supplierName: { type: Type.STRING, nullable: true },
          amountPayable: { type: Type.NUMBER, nullable: true },
          billingPeriod: { type: Type.STRING, nullable: true },
          currency: { type: Type.STRING, nullable: true },
          confidence: { type: Type.NUMBER },
          reasoning: { type: Type.STRING }
        },
        required: ["value", "unit", "detectedDataType", "confidence"]
      }
    }
  });

  return JSON.parse(response.text || "{}") as ExtractionResult;
};

import React, { useState, useEffect } from 'react';
import { DataType, RequestMetadata, SubmissionData, EMISSION_FACTORS, DATA_UNITS } from './types';
import { extractDataFromDocument } from './services/geminiService';

// --- Database Simulation (Local Storage) ---
const DB = {
  saveRequest: (req: RequestMetadata) => {
    const items = JSON.parse(localStorage.getItem('scope3_requests') || '[]');
    items.push(req);
    localStorage.setItem('scope3_requests', JSON.stringify(items));
  },
  getRequest: (id: string): RequestMetadata | undefined => {
    const items = JSON.parse(localStorage.getItem('scope3_requests') || '[]');
    return items.find((r: RequestMetadata) => r.id === id);
  },
  saveSubmission: (sub: SubmissionData) => {
    const items = JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
    items.push(sub);
    localStorage.setItem('scope3_submissions', JSON.stringify(items));
  },
  getSubmissions: (): SubmissionData[] => {
    return JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
  }
};

const Layout = ({ children }: { children: React.ReactNode }) => (
  <div className="min-h-screen flex flex-col">
    <nav className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center sticky top-0 z-10">
      <div className="flex items-center gap-3 cursor-pointer" onClick={() => window.location.hash = ''}>
        <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
          <span className="text-white font-black text-lg">S3</span>
        </div>
        <div>
          <span className="font-bold text-slate-900 block leading-tight">Scope 3</span>
          <span className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">Submission Tool</span>
        </div>
      </div>
      <div className="flex gap-6 text-sm font-semibold text-slate-500">
        <a href="#" className="hover:text-indigo-600 transition-colors">Request Center</a>
        <a href="#admin" className="hover:text-indigo-600 transition-colors">Buyer Dashboard</a>
      </div>
    </nav>
    <main className="flex-1 bg-slate-50/50">
      {children}
    </main>
  </div>
);

const BuyerPage = () => {
  const [buyerCompany, setBuyerCompany] = useState('');
  const [dataType, setDataType] = useState<DataType | 'ANY'>('ANY');
  const [period, setPeriod] = useState('FY 2024');
  const [generatedLink, setGeneratedLink] = useState('');

  const handleGenerate = () => {
    const id = Math.random().toString(36).substring(2, 9);
    const newRequest: RequestMetadata = {
      id,
      buyerCompanyName: buyerCompany,
      dataType,
      reportingPeriod: period,
      createdAt: Date.now(),
    };
    DB.saveRequest(newRequest);
    const link = `${window.location.origin}/#supplier/${id}`;
    setGeneratedLink(link);
  };

  return (
    <div className="max-w-xl mx-auto py-16 px-4">
      <header className="mb-10 text-center">
        <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Generate Request</h1>
        <p className="mt-3 text-slate-500 text-lg">Send a secure link to your suppliers to collect Scope 3 data.</p>
      </header>

      <div className="bg-white p-8 rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-100 space-y-6">
        <div>
          <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Company Name</label>
          <input 
            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-slate-900 focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none"
            placeholder="e.g. Global Tech Inc."
            value={buyerCompany}
            onChange={(e) => setBuyerCompany(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Data Type</label>
            <select 
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none focus:bg-white focus:border-indigo-500 transition-all"
              value={dataType}
              onChange={(e) => setDataType(e.target.value as any)}
            >
              <option value="ANY">Any Category</option>
              {Object.values(DataType).map(type => <option key={type} value={type}>{type}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Period</label>
            <input 
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none focus:bg-white focus:border-indigo-500 transition-all"
              value={period}
              onChange={(e) => setPeriod(e.target.value)}
            />
          </div>
        </div>

        <button 
          onClick={handleGenerate}
          disabled={!buyerCompany}
          className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl hover:bg-indigo-700 disabled:opacity-50 shadow-lg shadow-indigo-200 transition-all transform hover:-translate-y-0.5 active:translate-y-0"
        >
          Create Request Link
        </button>

        {generatedLink && (
          <div className="mt-8 p-6 bg-emerald-50 border border-emerald-100 rounded-2xl animate-in fade-in slide-in-from-bottom-2 duration-500">
            <p className="text-sm font-bold text-emerald-800 flex items-center gap-2 mb-3">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              Link Ready to Send
            </p>
            <div className="flex items-center gap-2">
              <input readOnly value={generatedLink} className="flex-1 text-sm p-3 rounded-lg border border-emerald-200 bg-white font-mono" />
              <button 
                onClick={() => {
                  navigator.clipboard.writeText(generatedLink);
                  alert('Link copied to clipboard!');
                }}
                className="bg-emerald-600 text-white px-4 py-3 rounded-lg text-sm font-bold hover:bg-emerald-700"
              >
                Copy
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const SupplierPage = ({ requestId }: { requestId: string }) => {
  const [request, setRequest] = useState<RequestMetadata | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  // Submission Form State
  const [extractedValue, setExtractedValue] = useState<number | ''>('');
  const [selectedType, setSelectedType] = useState<DataType>(DataType.ELECTRICITY);
  const [notes, setNotes] = useState('');
  const [confidence, setConfidence] = useState<number>(1);
  const [feedback, setFeedback] = useState<{msg: string, type: 'info' | 'warn' | 'error'} | null>(null);

  useEffect(() => {
    const r = DB.getRequest(requestId);
    if (r) {
      setRequest(r);
      if (r.dataType !== 'ANY') setSelectedType(r.dataType as DataType);
    }
  }, [requestId]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !request) return;

    setIsProcessing(true);
    setFeedback({ msg: "Analyzing document with Gemini AI...", type: 'info' });

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromDocument(base64);

        if (result.value !== null) {
          setExtractedValue(result.value);
          setConfidence(result.confidence);
          if (result.detectedDataType) setSelectedType(result.detectedDataType);

          if (result.confidence < 0.7) {
            setFeedback({ msg: "Extraction confidence is low. Please verify values manually.", type: 'warn' });
          } else {
            setFeedback({ msg: "Document analyzed successfully.", type: 'info' });
          }
        } else {
          setFeedback({ msg: "We couldn't extract the activity data. Please enter it manually.", type: 'warn' });
          setManualMode(true);
        }
      } catch (err) {
        setFeedback({ msg: "Error processing document. Please enter details manually.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = () => {
    if (!request || extractedValue === '') return;
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: request.id,
      buyerName: request.buyerCompanyName,
      activityValue: extractedValue,
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: extractedValue * factor,
      emissionFactor: factor,
      notes,
      timestamp: Date.now()
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

  if (!request) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center px-4">
      <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-4 text-2xl">⚠️</div>
      <h2 className="text-2xl font-bold text-slate-800">Invalid or Expired Link</h2>
      <p className="text-slate-500 mt-2">Please contact the buyer for a new submission link.</p>
    </div>
  );

  if (submitted) return (
    <div className="max-w-md mx-auto py-24 px-4 text-center">
      <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce shadow-xl shadow-emerald-100">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
      </div>
      <h2 className="text-3xl font-black text-slate-900">Submission Successful</h2>
      <p className="text-slate-500 mt-4 text-lg">Thank you! Your emissions data has been securely shared with <strong>{request.buyerCompanyName}</strong>.</p>
      <button 
        onClick={() => window.location.hash = ''} 
        className="mt-10 text-indigo-600 font-bold hover:underline"
      >
        Go to Homepage
      </button>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
    <div className="max-w-2xl mx-auto py-12 px-4">
      <div className="mb-10 text-center">
        <span className="inline-block bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider mb-4">Data Request</span>
        <h1 className="text-4xl font-black text-slate-900 tracking-tight">Report for {request.buyerCompanyName}</h1>
        <p className="text-slate-500 mt-2 text-lg">Targeting {request.dataType} data for {request.reportingPeriod}.</p>
      </div>

      <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200 border border-slate-100 overflow-hidden">
        <div className="p-8 bg-slate-900 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <svg className="w-6 h-6 text-indigo-400" fill="currentColor" viewBox="0 0 20 20"><path d="M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3zM6 8a2 2 0 11-4 0 2 2 0 014 0zM16 18v-3a5.972 5.972 0 00-.75-2.906A3.005 3.005 0 0119 15v3h-3zM4.75 12.094A5.973 5.973 0 004 15v3H1v-3a3 3 0 013.75-2.906z"></path></svg>
            AI Assistant
          </h2>
          <p className="text-slate-400 text-sm mt-1 font-medium">Upload your bills. We'll handle the extraction.</p>
        </div>

        <div className="p-8 space-y-8">
          {!manualMode && !extractedValue && (
            <div className="relative">
              <div className={`border-3 border-dashed rounded-3xl p-16 text-center transition-all ${isProcessing ? 'border-indigo-400 bg-indigo-50/50' : 'border-slate-200 hover:border-indigo-400 hover:bg-slate-50'}`}>
                {isProcessing ? (
                  <div className="flex flex-col items-center gap-4">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-4 border-indigo-600 border-r-4 border-r-transparent"></div>
                    <p className="text-indigo-600 font-bold animate-pulse">Gemini is reading your document...</p>
                  </div>
                ) : (
                  <>
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileUpload} accept="image/*,application/pdf" />
                    <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
                      <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path></svg>
                    </div>
                    <p className="text-xl font-extrabold text-slate-800">Drop your file here</p>
                    <p className="text-slate-500 mt-2 font-medium">Bills, receipts, or invoices (PNG, JPG, PDF)</p>
                    <button className="mt-8 px-6 py-2 bg-slate-900 text-white font-bold rounded-lg text-sm hover:bg-slate-800">Browse Files</button>
                    <div className="mt-6 pt-6 border-t border-slate-100">
                      <button onClick={() => setManualMode(true)} className="text-indigo-600 text-sm font-bold hover:underline">Or enter data manually</button>
                    </div>
                  </>
                )}
              </div>
            </div>
          )}

          {(extractedValue !== '' || manualMode) && (
            <div className="space-y-6 animate-in fade-in duration-700">
              {feedback && (
                <div className={`p-4 rounded-xl flex items-start gap-3 ${
                  feedback.type === 'warn' ? 'bg-amber-50 text-amber-800 border border-amber-200' : 
                  feedback.type === 'error' ? 'bg-red-50 text-red-800 border border-red-200' : 
                  'bg-indigo-50 text-indigo-800 border border-indigo-200'
                }`}>
                  <span className="text-xl">{feedback.type === 'warn' ? '⚡' : feedback.type === 'error' ? '❌' : '✨'}</span>
                  <p className="text-sm font-bold">{feedback.msg}</p>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Category</label>
                  <select 
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none focus:bg-white focus:border-indigo-500 transition-all font-bold"
                    value={selectedType}
                    onChange={(e) => setSelectedType(e.target.value as DataType)}
                  >
                    {Object.values(DataType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Usage ({unit})</label>
                  <input 
                    type="number" className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none focus:bg-white focus:border-indigo-500 transition-all font-bold text-lg"
                    value={extractedValue}
                    onChange={(e) => setExtractedValue(e.target.value === '' ? '' : parseFloat(e.target.value))}
                  />
                </div>
              </div>

              <div className="relative overflow-hidden bg-gradient-to-br from-indigo-600 to-indigo-800 p-8 rounded-3xl text-white shadow-xl shadow-indigo-100">
                <div className="relative z-10 flex justify-between items-end">
                  <div>
                    <p className="text-indigo-200 text-xs font-black uppercase tracking-widest mb-1">Calculated Impact</p>
                    <p className="text-5xl font-black">{calculatedEmissions} <span className="text-xl">kgCO₂e</span></p>
                  </div>
                  <div className="text-right">
                    <p className="text-indigo-200 text-[10px] font-bold uppercase mb-1">Factor Used</p>
                    <p className="text-sm font-bold bg-white/10 px-2 py-1 rounded backdrop-blur-sm">{factor} / {unit}</p>
                  </div>
                </div>
                <div className="absolute top-0 right-0 -mr-12 -mt-12 w-48 h-48 bg-white/5 rounded-full blur-2xl"></div>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Internal Notes (Optional)</label>
                <textarea 
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 outline-none focus:bg-white focus:border-indigo-500 transition-all font-medium text-sm min-h-[100px]"
                  placeholder="Reference number, project name, etc."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                />
              </div>

              <div className="flex gap-4">
                <button 
                  onClick={() => { setExtractedValue(''); setManualMode(false); setFeedback(null); }}
                  className="flex-1 bg-slate-100 text-slate-600 font-bold py-4 rounded-xl hover:bg-slate-200 transition-all"
                >
                  Start Over
                </button>
                <button 
                  onClick={handleSubmit} 
                  className="flex-[2] bg-indigo-600 text-white font-black py-4 rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all transform hover:-translate-y-0.5"
                >
                  Submit Final Report
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const AdminViewer = () => {
  const [submissions, setSubmissions] = useState<SubmissionData[]>([]);

  useEffect(() => {
    setSubmissions(DB.getSubmissions());
  }, []);

  const downloadCSV = () => {
    const headers = ['ID', 'Buyer', 'Category', 'Activity Value', 'Unit', 'Emissions (kgCO2e)', 'Date'];
    const rows = submissions.map(s => [
      s.id, s.buyerName, s.dataType, s.activityValue, s.unit, s.emissionsKgCO2e.toFixed(2), new Date(s.timestamp).toLocaleDateString()
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "scope3_submissions.csv");
    document.body.appendChild(link);
    link.click();
  };

  return (
    <div className="max-w-6xl mx-auto py-12 px-6">
      <div className="flex justify-between items-center mb-10">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Buyer Dashboard</h1>
          <p className="text-slate-500 mt-2 font-medium">Reviewing {submissions.length} total supplier submissions.</p>
        </div>
        <button 
          onClick={downloadCSV}
          disabled={submissions.length === 0}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold text-sm flex items-center gap-2 hover:bg-slate-800 transition-all disabled:opacity-50"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
          Export CSV
        </button>
      </div>

      <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
        {submissions.length === 0 ? (
          <div className="p-24 text-center">
            <div className="w-20 h-20 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"></path></svg>
            </div>
