import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  const prompt = `
    ROLE: You are an expert sustainability data auditor.
    TASK: Analyze the provided document to extract Scope 3 activity data for carbon reporting.

    DOCUMENT TYPES & TARGETS:
    1. Electricity Bill (e.g., Tenaga Nasional): 
       - Look for "Penggunaan" or "Usage" in kWh. 
       - Identify "Tenaga Nasional Berhad" as the supplier.
    2. Fuel/Fleet Report (e.g., Petronas SmartPay):
       - Look for "Kuantiti Belian" or "Total Volume" in Liters.
       - Identify if it is "Diesel" or "Primax (Petrol)".
       - Identify "Petronas" as the supplier.
    3. Transport/Logistics:
       - Look for "Distance", "km", or "Odometer" difference.

    RULES:
    - If the document lists multiple transactions, extract the SUM or the "Jumlah" (Total) for the reporting period.
    - DetectedDataType must be one of: "Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport".
    - "value" must be a number only (no units).
    - "confidence" should be high (0.9+) if you found a "Total" or "Jumlah" label next to the value.
    - Set missing metadata to null.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: "image/jpeg", data: base64Image } }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          value: { type: Type.NUMBER, nullable: true },
          unit: { type: Type.STRING, nullable: true },
          detectedDataType: { 
            type: Type.STRING, 
            enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
          },
          supplierName: { type: Type.STRING, nullable: true },
          amountPayable: { type: Type.NUMBER, nullable: true },
          billingPeriod: { type: Type.STRING, nullable: true },
          currency: { type: Type.STRING, nullable: true },
          confidence: { type: Type.NUMBER },
          reasoning: { type: Type.STRING }
        },
        required: ["value", "unit", "detectedDataType", "confidence"]
      }
    }
  });

  return JSON.parse(response.text || "{}") as ExtractionResult;
};

