        const result = await extractDataFromDocument(base64);

        if (result.value !== null) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType);
          if (result.supplierName) setCompanyName(result.supplierName);

          if (result.confidence < 0.8) {
            setFeedback({ msg: `Found ${result.value} ${result.unit}, but confidence is low. Please verify.`, type: 'warn' });
          } else {
            setFeedback({ msg: "Data successfully extracted from document.", type: 'info' });
          }
        } else {
          setFeedback({ msg: "Could not find clear activity values. Please enter manually.", type: 'warn' });
          setManualMode(true);
        }
      } catch (err) {
        setFeedback({ msg: "Processing error. Please use manual entry.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!companyName || extractedValue === '') {
      alert("Company Name and Activity Value are required.");
      return;
    }
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: 'DIRECT_GEN',
      buyerName: companyName,
      activityValue: Number(extractedValue),
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: Number(extractedValue) * factor,
      emissionFactor: factor,
      notes,
      timestamp: Date.now()
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

  if (submitted) return (
    <div className="max-w-md mx-auto py-24 px-4 text-center animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-emerald-100">
