      </div>
      <h2 className="text-3xl font-black text-slate-900 tracking-tight">Report Generated</h2>
      <p className="text-slate-500 mt-4 text-lg">Emission record has been stored in your history.</p>
      <div className="flex gap-4 mt-10">
        <button onClick={() => window.location.reload()} className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 transition-all">New Report</button>
        <button onClick={() => window.location.hash = '#history'} className="flex-1 bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-all">History</button>
      </div>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
