import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  const prompt = `
    ROLE: You are an expert sustainability data auditor specialized in Malaysian utility and fuel reports.
    TASK: Analyze the provided document images (Electricity bill or Petronas Fleet Report) to extract total activity data.

    SPECIFIC DOCUMENT HANDLING:
    1. Tenaga Nasional (TNB) Bill:
       - Look for the "Maklumat Meter" table or "Jumlah Penggunaan Anda" section.
       - Extract the value in the "Penggunaan" or "Usage" column (e.g., 69 kWh).
       - Supplier: "Tenaga Nasional Berhad".
       - DataType: "Electricity".

    2. Petronas SmartPay / Fleet Report:
       - Look for "HURAIAN RINGKASAN BAHAN" or "PENYATA AKAUN" summaries.
       - Locate the "KUANTITI BELIAN (LTR/UNIT)" column.
       - For Petrol, look for "PRIMAX 95" or "PTRL".
       - For Diesel, look for "Diesel EURO 5" or "DISL".
       - Extract the total sum value for the relevant fuel type.
       - Supplier: "Petronas".

    RULES:
    - Return ONLY the most significant "Total" or "Jumlah" value found for the current period.
    - Set 'value' as a pure number.
    - Set 'detectedDataType' as exactly one of: "Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport".
    - Confidence score (0-1) reflects clarity of the 'Total' figure.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: "image/jpeg", data: base64Image } }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          value: { type: Type.NUMBER, nullable: true },
          unit: { type: Type.STRING, nullable: true },
          detectedDataType: { 
            type: Type.STRING, 
            enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
          },
          supplierName: { type: Type.STRING, nullable: true },
          amountPayable: { type: Type.NUMBER, nullable: true },
          billingPeriod: { type: Type.STRING, nullable: true },
          currency: { type: Type.STRING, nullable: true },
          confidence: { type: Type.NUMBER },
          reasoning: { type: Type.STRING }
        },
        required: ["value", "unit", "detectedDataType", "confidence"]
      }
    }
  });

  try {
    const text = response.text.trim();
    // Handling potential markdown block in response
    const cleanJson = text.startsWith('```') ? text.replace(/^```json\n|```$/g, '') : text;
    return JSON.parse(cleanJson) as ExtractionResult;
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    throw new Error("Data extraction failed to produce valid JSON");
  }
};

import React, { useState, useEffect } from 'react';
import { DataType, SubmissionData, EMISSION_FACTORS, DATA_UNITS } from './types';
import { extractDataFromDocument } from './services/geminiService';

// --- Database Simulation (Local Storage) ---
const DB = {
  saveSubmission: (sub: SubmissionData) => {
    const items = JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
    items.push(sub);
    localStorage.setItem('scope3_submissions', JSON.stringify(items));
  },
  getSubmissions: (): SubmissionData[] => {
    return JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
  }
};

