const SubmissionTool = () => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [extractedValue, setExtractedValue] = useState<number | ''>('');
  const [selectedType, setSelectedType] = useState<DataType>(DataType.ELECTRICITY);
  const [companyName, setCompanyName] = useState('');
  const [notes, setNotes] = useState('');
  const [feedback, setFeedback] = useState<{msg: string, type: 'info' | 'warn' | 'error'} | null>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setFeedback({ msg: "Gemini AI is scanning pages for usage data...", type: 'info' });

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromDocument(base64);

        if (result && result.value !== null) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType);
          if (result.supplierName) setCompanyName(result.supplierName);

          if (result.confidence < 0.7) {
            setFeedback({ msg: `Found ${result.value} ${result.unit}, but the match is low confidence. Please verify.`, type: 'warn' });
          } else {
            setFeedback({ msg: `Successfully extracted ${result.value} ${result.unit} from ${result.supplierName || 'document'}.`, type: 'info' });
          }
        } else {
          setFeedback({ msg: "Could not find a 'Total' usage figure. Please enter it manually.", type: 'warn' });
          setManualMode(true);
        }
      } catch (err) {
        console.error(err);
        setFeedback({ msg: "Could not read this document format. Switching to manual entry.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!companyName || extractedValue === '') {
      alert("Supplier name and activity value are required to save.");
      return;
    }
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: 'DIRECT_GEN',
      buyerName: companyName,
      activityValue: Number(extractedValue),
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: Number(extractedValue) * factor,
      emissionFactor: factor,
      notes,
      timestamp: Date.now()
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

  if (submitted) return (
    <div className="max-w-md mx-auto py-24 px-4 text-center animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-emerald-100">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
      </div>
      <h2 className="text-3xl font-black text-slate-900 tracking-tight">Report Saved</h2>
      <p className="text-slate-500 mt-4 text-lg">Your Scope 3 record has been archived in the history log.</p>
      <div className="flex gap-4 mt-10">
        <button onClick={() => window.location.reload()} className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all">New Entry</button>
        <button onClick={() => window.location.hash = '#history'} className="flex-1 bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 shadow-lg transition-all">View Log</button>
      </div>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
    <div className="max-w-3xl mx-auto py-12 px-4">
      <div className="mb-10 text-center">
        <h1 className="text-4xl font-black text-slate-900 tracking-tight">Scope 3 Report Generator</h1>
