import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  const prompt = `
    ROLE: You are an expert sustainability data auditor specialized in high-accuracy OCR for Malaysian utility and fuel reports.

    TASK: Analyze the provided document image to extract the primary activity usage value (kWh or Liters).

    EXTRACTION STRATEGY:
    1. Tenaga Nasional (TNB) Bill:
       - Search for "Penggunaan (kWh)" or "Jumlah Penggunaan Anda".
       - Look for a numeric value associated with "kWh" or "kwh" in the "Maklumat Meter" or usage table.
       - Extract "Tenaga Nasional Berhad" as supplierName.
       - Category: "Electricity".

    2. Petronas SmartPay / Fleet Report:
       - Focus on "HURAIAN RINGKASAN BAHAN" or "LAPORAN ANALISA KENDERAAN".
       - Locate the "KUANTITI BELIAN (LTR/UNIT)" or "Qty" column.
       - Sum the total volume if multiple lines exist, or extract the "Jumlah" (Total) value.
       - Distinguish between "Diesel" (Fuel (Diesel)) and "Primax/Petrol" (Fuel (Petrol)).
       - Extract "Petronas" as supplierName.

    OUTPUT REQUIREMENTS:
    - value: The raw numeric usage (e.g., 69 or 1886.035). No commas or units.
    - unit: "kWh" for electricity, "liters" for fuel.
    - detectedDataType: One of [Electricity, Fuel (Diesel), Fuel (Petrol), Transport].
    - confidence: 0.95 if the "Total" label is clearly mapped, lower otherwise.

    Return the result in valid JSON format only.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: "image/jpeg", data: base64Image } }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          value: { type: Type.NUMBER, nullable: true },
          unit: { type: Type.STRING, nullable: true },
          detectedDataType: { 
            type: Type.STRING, 
            enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
          },
          supplierName: { type: Type.STRING, nullable: true },
          amountPayable: { type: Type.NUMBER, nullable: true },
          billingPeriod: { type: Type.STRING, nullable: true },
          currency: { type: Type.STRING, nullable: true },
          confidence: { type: Type.NUMBER },
          reasoning: { type: Type.STRING }
        },
        required: ["value", "unit", "detectedDataType", "confidence"]
      }
    }
  });

  try {
    const text = response.text.trim();
    const cleanJson = text.startsWith('```') ? text.replace(/^```json\n|```$/g, '') : text;
    const parsed = JSON.parse(cleanJson) as ExtractionResult;

    // Safety check for common extraction errors
    if (parsed.value === 0 || parsed.value === null) {
        throw new Error("Zero or null value extracted");
    }

    return parsed;
  } catch (e) {
    console.error("Gemini Extraction Error:", e);
    throw new Error("The AI could not confidently locate usage data. Please try again or use manual entry.");
  }
};

import React, { useState, useEffect } from 'react';
