import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  // Initialize inside function to ensure fresh API key context if needed
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    ROLE: Expert sustainability data auditor for Malaysian utility/fuel reports.
    TASK: Extract primary usage (kWh or Liters) from the provided image.

    STRATEGY:
    1. TNB Bill: Look for "Penggunaan (kWh)" or "Jumlah Penggunaan" table. Find the numeric value for current usage. Supplier: "Tenaga Nasional Berhad".
    2. Petronas SmartPay: Look for "KUANTITI BELIAN" or "Qty" in summary tables. Sum volumes for "Diesel" or "Primax/Petrol". Supplier: "Petronas".

    OUTPUT: Return valid JSON with numeric 'value', 'unit', and 'detectedDataType'.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: "image/png",
                data: base64Image,
              },
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            value: { type: Type.NUMBER, description: "The usage amount (numeric only)" },
            unit: { type: Type.STRING, description: "kWh or Liters" },
            detectedDataType: { 
              type: Type.STRING, 
              enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
            },
            supplierName: { type: Type.STRING },
            confidence: { type: Type.NUMBER, description: "Score 0-1" },
            reasoning: { type: Type.STRING }
          },
          required: ["value", "unit", "detectedDataType", "confidence"],
        },
      },
    });

    const resultText = response.text;
    if (!resultText) {
      throw new Error("Empty response from Gemini API");
    }

    const parsed = JSON.parse(resultText) as ExtractionResult;
    return parsed;
  } catch (e: any) {
    console.error("Gemini API Error:", e);
    throw new Error(e.message || "Failed to call Gemini API");
  }
};

