    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromDocument(base64);

        if (result && result.value) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType);
          if (result.supplierName) setCompanyName(result.supplierName);

          setFeedback({ 
            msg: `Successfully extracted ${result.value} ${result.unit} from ${result.supplierName || 'document'}.`, 
            type: result.confidence < 0.8 ? 'warn' : 'info' 
          });
        } else {
          throw new Error("No data returned from AI");
        }
      } catch (err: any) {
        console.error("Submission error:", err);
