import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  // Ensure we have a clean base64 string without data URL prefix if present
  const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    ROLE: Expert Sustainability Data Auditor.
    TASK: Extract primary activity data (kWh or Liters) for Scope 3 reporting.

    DOCUMENTS GUIDELINES:
    1. TNB Bill (Electricity):
       - Look for "Penggunaan (kWh)" or "Usage".
       - Locate the numeric value under "Penggunaan" in meter tables.
       - Supplier: "Tenaga Nasional Berhad".

    2. Petronas SmartPay (Fuel):
       - Look for tables titled "LAPORAN ANALISA KENDERAAN" or "HURAIAN RINGKASAN BAHAN".
       - Find the "KUANTITI BELIAN (LTR/UNIT)" or "Qty" column.
       - Sum volumes for "Diesel" vs "Primax/Petrol" as separate items if needed, but return the dominant total for this extraction.
       - Supplier: "Petronas".

    STRATEGY: Use the provided image to identify the merchant and the TOTAL usage for the period.
    OUTPUT: Return a valid JSON object matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: "image/png",
                data: cleanBase64,
              },
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            value: { type: Type.NUMBER, description: "Numeric usage amount extracted" },
            unit: { type: Type.STRING, description: "kWh or Liters" },
            detectedDataType: { 
              type: Type.STRING, 
              enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
            },
            supplierName: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
            reasoning: { type: Type.STRING }
          },
          required: ["value", "unit", "detectedDataType", "confidence"],
        },
      },
    });

    const resultText = response.text;
    if (!resultText) {
      throw new Error("Gemini returned an empty response.");
    }

    return JSON.parse(resultText) as ExtractionResult;
  } catch (e: any) {
    console.error("Gemini API Error:", e);
    // If it's the 400 image error, try to provide a more descriptive message
    if (e.message?.includes("400") || e.message?.includes("INVALID_ARGUMENT")) {
      throw new Error("The image format or size was rejected by the AI. Please try a different screenshot or manual entry.");
    }
    throw new Error(e.message || "Failed to process document.");
  }
};

