            supplierName: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
            reasoning: { type: Type.STRING }
          },
          required: ["value", "unit", "detectedDataType", "confidence"],
        },
      },
    });

    const resultText = response.text;
    if (!resultText) {
      throw new Error("Gemini returned an empty response.");
    }

    return JSON.parse(resultText) as ExtractionResult;
  } catch (e: any) {
    console.error("Gemini API Error details:", e);

    // Explicitly handle the 400 error which usually indicates base64 or mimeType issues
    if (e.message?.includes("400") || e.message?.includes("INVALID_ARGUMENT") || e.message?.includes("process input image")) {
      throw new Error("AI was unable to process the image bytes. Please try taking a clearer screenshot or smaller photo.");
    }

    throw new Error(e.message || "Failed to process document.");
  }
};

