const SubmissionTool = () => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [extractedValue, setExtractedValue] = useState<number | ''>('');
  const [selectedType, setSelectedType] = useState<DataType>(DataType.ELECTRICITY);
  const [companyName, setCompanyName] = useState('');
  const [notes, setNotes] = useState('');
  const [feedback, setFeedback] = useState<{msg: string, type: 'info' | 'warn' | 'error'} | null>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // API limit check - high res images can cause 400 errors
    if (file.size > 5 * 1024 * 1024) {
      setFeedback({ msg: "File too large (>5MB). Please upload a smaller image or screenshot.", type: 'error' });
      return;
    }

    setIsProcessing(true);
    setFeedback({ msg: "Gemini AI is analyzing document bytes...", type: 'info' });

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64Data = reader.result as string;
        const result = await extractDataFromDocument(base64Data);

        if (result && result.value) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType as DataType);
          if (result.supplierName) setCompanyName(result.supplierName);

          setFeedback({ 
            msg: `Found ${result.value} ${result.unit} from ${result.supplierName || 'document'}.`, 
            type: result.confidence < 0.8 ? 'warn' : 'info' 
          });
        } else {
          throw new Error("AI could not detect usage values.");
        }
      } catch (err: any) {
        console.error("Submission error:", err);
        setFeedback({ msg: err.message || "Extraction failed. Entering manual mode.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.onerror = () => {
      setFeedback({ msg: "Browser failed to read the file.", type: 'error' });
      setIsProcessing(false);
    };
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!companyName || extractedValue === '') {
      alert("Supplier name and activity value are required.");
      return;
    }
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: 'DIRECT_GEN',
      buyerName: companyName,
      activityValue: Number(extractedValue),
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: Number(extractedValue) * factor,
      emissionFactor: factor,
      notes,
      timestamp: Date.now()
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

