        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
      </div>
      <h2 className="text-3xl font-black text-slate-900 tracking-tight">Report Saved</h2>
      <p className="text-slate-500 mt-4 text-lg">Submission archived successfully.</p>
      <div className="flex gap-4 mt-10">
        <button onClick={() => window.location.reload()} className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 transition-all shadow-lg">New Entry</button>
        <button onClick={() => window.location.hash = '#history'} className="flex-1 bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-all shadow-lg">View History</button>
      </div>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
    <div className="max-w-3xl mx-auto py-12 px-4">
      <div className="mb-10 text-center">
        <h1 className="text-4xl font-black text-slate-900 tracking-tight">Scope 3 Submission</h1>
