import { GoogleGenAI, Type } from "@google/genai";
import { DataType, ExtractionResult } from "../types";

export const extractDataFromDocument = async (
  base64Image: string
): Promise<ExtractionResult> => {
  // Clean base64 string
  const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  // Initializing with the system provided API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Analyze this document (utility bill or fuel receipt) and extract Scope 3 emissions data.

    GUIDELINES:
    1. TNB Bill (Electricity):
       - Find "Penggunaan (kWh)" or usage total.
       - Supplier: "Tenaga Nasional Berhad".

    2. Petronas SmartPay (Fuel):
       - Find "KUANTITI BELIAN (LTR)" or total volume.
       - Supplier: "Petronas".

    Format the output as a JSON object with:
    - value (number): the numeric quantity found.
    - unit (string): 'kWh' or 'liters'.
    - detectedDataType (string): 'Electricity', 'Fuel (Diesel)', or 'Fuel (Petrol)'.
    - supplierName (string): name of the issuer.
    - confidence (number): score between 0 and 1.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: "image/jpeg",
                data: cleanBase64,
              },
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            value: { type: Type.NUMBER },
            unit: { type: Type.STRING },
            detectedDataType: { 
              type: Type.STRING, 
              enum: ["Electricity", "Fuel (Diesel)", "Fuel (Petrol)", "Transport"]
            },
            supplierName: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
            reasoning: { type: Type.STRING }
          },
          required: ["value", "unit", "detectedDataType", "confidence"],
        },
      },
    });

    const resultText = response.text;
    if (!resultText) {
      throw new Error("No text returned from Gemini.");
    }

    return JSON.parse(resultText) as ExtractionResult;
  } catch (e: any) {
    console.error("Gemini Extraction Error:", e);

    // Check for specific error patterns
    if (e.message?.includes("400") || e.message?.includes("INVALID_ARGUMENT")) {
      throw new Error("Gemini API rejected the image format or size. Please try a standard JPEG/PNG image under 4MB.");
    }

    throw new Error(e.message || "Failed to extract data from document.");
  }
};

