          <span className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">Extraction Tool</span>
        </div>
      </div>
      <div className="flex gap-4 md:gap-6 text-sm font-semibold text-slate-500">
        <a href="#" className="hover:text-indigo-600 transition-colors py-2">Create Report</a>
        <a href="#history" className="hover:text-indigo-600 transition-colors py-2">History</a>
