);

const SubmissionTool = () => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [extractedValue, setExtractedValue] = useState<number | ''>('');
  const [selectedType, setSelectedType] = useState<DataType>(DataType.ELECTRICITY);
  const [companyName, setCompanyName] = useState('');
  const [notes, setNotes] = useState('');
  const [feedback, setFeedback] = useState<{msg: string, type: 'info' | 'warn' | 'error'} | null>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // API limit check
    if (file.size > 10 * 1024 * 1024) {
      setFeedback({ msg: "File too large (>10MB). Please upload a smaller file.", type: 'error' });
      return;
    }

    setIsProcessing(true);
    setFeedback({ msg: "AI is processing your file...", type: 'info' });

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64Data = reader.result as string;
        const result = await extractDataFromDocument(base64Data, file.type || "image/jpeg");

        if (result && result.value !== null) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType as DataType);
          if (result.supplierName) setCompanyName(result.supplierName);

          setFeedback({ 
            msg: `Successfully extracted ${result.value} ${result.unit} from ${result.supplierName || 'document'}.`, 
            type: result.confidence < 0.8 ? 'warn' : 'info' 
          });
        } else {
          throw new Error("AI could not detect usage values in this document.");
        }
      } catch (err: any) {
        console.error("Extraction error:", err);
        setFeedback({ msg: err.message || "Extraction failed. Entering manual mode.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.onerror = () => {
      setFeedback({ msg: "Browser failed to read the file.", type: 'error' });
      setIsProcessing(false);
    };
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!companyName || extractedValue === '') {
      alert("Supplier name and activity value are required.");
      return;
    }
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: 'DIRECT_GEN',
      buyerName: companyName,
      activityValue: Number(extractedValue),
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: Number(extractedValue) * factor,
      emissionFactor: factor,
      notes,
      timestamp: Date.now()
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

  if (submitted) return (
    <div className="max-w-md mx-auto py-24 px-4 text-center animate-in fade-in duration-500">
      <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-emerald-100">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
      </div>
      <h2 className="text-3xl font-black text-slate-900 tracking-tight">Report Saved</h2>
      <p className="text-slate-500 mt-4 text-lg">Submission archived successfully.</p>
      <div className="flex gap-4 mt-10">
        <button onClick={() => window.location.reload()} className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 transition-all shadow-lg">New Entry</button>
        <button onClick={() => window.location.hash = '#history'} className="flex-1 bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-all shadow-lg">View History</button>
      </div>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
    <div className="max-w-3xl mx-auto py-12 px-4">
      <div className="mb-10 text-center">
        <h1 className="text-4xl font-black text-slate-900 tracking-tight">Scope 3 Submission</h1>
        <p className="text-slate-500 mt-2 text-lg font-medium">Automatic extraction for TNB and Petronas documents.</p>
      </div>

      <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200 border border-slate-100 overflow-hidden">
        <div className="p-8 bg-slate-900 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2">
              <svg className="w-6 h-6 text-indigo-400" fill="currentColor" viewBox="0 0 20 20"><path d="M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3zM6 8a2 2 0 11-4 0 2 2 0 014 0zM16 18v-3a5.972 5.972 0 00-.75-2.906A3.005 3.005 0 0119 15v3h-3zM4.75 12.094A5.973 5.973 0 004 15v3H1v-3a3 3 0 013.75-2.906z"></path></svg>
              Smart Extraction
            </h2>
            <p className="text-slate-400 text-xs mt-1 uppercase tracking-widest font-bold">Image & PDF Scanner</p>
          </div>
          {(extractedValue !== '' || manualMode) && (
            <button onClick={() => { setExtractedValue(''); setManualMode(false); setFeedback(null); }} className="text-xs font-bold text-indigo-400 hover:text-white transition-colors">Reset</button>
          )}
        </div>

        <div className="p-8 space-y-8">
          {!manualMode && !extractedValue && (
            <div className={`relative border-3 border-dashed rounded-3xl p-16 text-center transition-all ${isProcessing ? 'border-indigo-400 bg-indigo-50/50' : 'border-slate-200 hover:border-indigo-400 hover:bg-slate-50'}`}>
              {isProcessing ? (
                <div className="flex flex-col items-center gap-6 py-8">
                  <div className="animate-spin rounded-full h-14 w-14 border-t-4 border-indigo-600 border-r-4 border-r-transparent"></div>
                  <div className="space-y-1">
                    <p className="text-indigo-600 font-black text-lg animate-pulse tracking-tight">AI Analysis in Progress...</p>
                    <p className="text-slate-400 text-sm font-medium">Scanning document totals</p>
                  </div>
                </div>
              ) : (
                <>
                  <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileUpload} accept="image/*,application/pdf" />
                  <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path></svg>
                  </div>
                  <p className="text-2xl font-black text-slate-800">Upload Receipt or Bill</p>
                  <p className="text-slate-500 mt-2 font-medium text-sm">Upload PDF, JPG or PNG (max 10MB)</p>
                  <button className="mt-8 px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl text-sm shadow-xl shadow-indigo-100 hover:scale-105 transition-all">Select File</button>
                  <button onClick={() => setManualMode(true)} className="block w-full mt-8 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] hover:text-indigo-600 transition-colors">Skip to Manual Entry</button>
                </>
              )}
            </div>
          )}

          {(extractedValue !== '' || manualMode) && (
            <div className="space-y-6 animate-in fade-in zoom-in-95 duration-500">
              {feedback && (
                <div className={`p-5 rounded-2xl flex items-start gap-3 border-2 ${
                  feedback.type === 'warn' ? 'bg-amber-50 text-amber-900 border-amber-100' : 
                  feedback.type === 'error' ? 'bg-red-50 text-red-900 border-red-100' : 
                  'bg-emerald-50 text-emerald-900 border-emerald-100'
                }`}>
                  <span className="text-2xl">{feedback.type === 'warn' ? '🔍' : feedback.type === 'error' ? '🚫' : '✅'}</span>
                  <p className="text-sm font-black leading-tight">{feedback.msg}</p>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Supplier</label>
                  <input 
                    className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 text-slate-900 font-bold focus:bg-white focus:border-indigo-600 transition-all outline-none"
                    placeholder="e.g. Tenaga Nasional"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Emission Category</label>
                  <select 
                    className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 outline-none focus:bg-white focus:border-indigo-600 transition-all font-bold appearance-none cursor-pointer"
                    value={selectedType}
                    onChange={(e) => setSelectedType(e.target.value as DataType)}
                  >
                    {Object.values(DataType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Quantity ({unit})</label>
                  <input 
                    type="number" className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 outline-none focus:bg-white focus:border-indigo-600 transition-all font-black text-2xl"
                    value={extractedValue}
                    onChange={(e) => setExtractedValue(e.target.value === '' ? '' : parseFloat(e.target.value))}
                  />
                </div>
              </div>

              <div className="bg-gradient-to-br from-indigo-600 to-indigo-900 p-8 rounded-[2rem] text-white shadow-2xl shadow-indigo-200 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-indigo-200 text-[10px] font-black uppercase tracking-widest mb-2">Total Carbon Impact</p>
                  <p className="text-6xl font-black tabular-nums">{calculatedEmissions} <span className="text-xl font-bold opacity-60">kgCO₂e</span></p>
                </div>
                <div className="bg-white/10 p-6 rounded-3xl backdrop-blur-xl border border-white/20 w-full md:w-auto relative z-10">
                  <p className="text-indigo-100 text-[9px] font-black uppercase mb-3 opacity-60 tracking-widest">Calculated using {factor} EF</p>
                  <div className="flex items-center gap-4 text-lg font-black font-mono">
                    <span className="text-indigo-200">{extractedValue || 0}</span>
                    <span className="text-white/40">×</span>
                    <span className="text-indigo-200">{factor}</span>
                  </div>
                </div>
              </div>

              <div className="pt-4">
                <button 
                  onClick={handleSave} 
                  className="w-full bg-slate-900 text-white font-black py-5 rounded-[1.5rem] hover:bg-slate-800 shadow-2xl transition-all transform hover:-translate-y-1 active:scale-95"
                >
                  Confirm & Submit Record
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

