export default function App() {
  const [hash, setHash] = useState(window.location.hash);
  useEffect(() => {
    const handleHash = () => setHash(window.location.hash);
    window.addEventListener('hashchange', handleHash);
    return () => window.removeEventListener('hashchange', handleHash);
  }, []);

  return <Layout>{hash === '#history' ? <HistoryPage /> : <SubmissionTool />}</Layout>;
}

import React, { useState, useEffect } from 'react';
import { DataType, SubmissionData, EMISSION_FACTORS, DATA_UNITS } from './types';
import { extractDataFromDocument } from './services/geminiService';

const DB = {
  saveSubmission: (sub: SubmissionData) => {
    const items = JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
    items.push(sub);
    localStorage.setItem('scope3_submissions', JSON.stringify(items));
  },
  getSubmissions: (): SubmissionData[] => {
    return JSON.parse(localStorage.getItem('scope3_submissions') || '[]');
  }
};

const Layout = ({ children }: { children: React.ReactNode }) => (
  <div className="min-h-screen flex flex-col bg-slate-50/50">
    <nav className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center sticky top-0 z-50 shadow-sm">
      <div className="flex items-center gap-3 cursor-pointer" onClick={() => window.location.hash = ''}>
        <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
          <span className="text-white font-black text-lg">S3</span>
        </div>
        <div>
          <span className="font-bold text-slate-900 block leading-tight">Scope 3</span>
          <span className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">Extraction Tool</span>
        </div>
      </div>
      <div className="flex gap-4 md:gap-6 text-sm font-semibold text-slate-500">
        <a href="#create" className="hover:text-indigo-600 transition-colors py-2">Create Request</a>
        <a href="#history" className="hover:text-indigo-600 transition-colors py-2">History</a>
      </div>
    </nav>
    <main className="flex-1 pb-20">{children}</main>
  </div>
);

const CreateRequest = () => {
  const [buyerName, setBuyerName] = useState('');
  const [dataType, setDataType] = useState<DataType | 'ANY'>('ANY');
