    <div className="max-w-2xl mx-auto py-12 px-4 animate-in fade-in duration-500">
      <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-2">Create Data Request</h1>
      <p className="text-slate-500 mb-10 text-lg font-medium">Generate a secure link to send to your suppliers.</p>

      <div className="bg-white rounded-[2rem] p-8 shadow-2xl shadow-slate-200 border border-slate-100 space-y-6">
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Your Company Name</label>
          <input 
            className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all"
            placeholder="Enter company name"
            value={buyerName}
            onChange={(e) => setBuyerName(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Data Type Requested</label>
            <select 
              className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-bold outline-none appearance-none"
              value={dataType}
              onChange={(e) => setDataType(e.target.value as DataType)}
