          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Reporting Period</label>
            <input 
              className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-bold outline-none"
              placeholder="e.g. Q3 2024"
