            <p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-3">Unique Supplier Link</p>
            <div className="flex gap-2">
              <input 
                readOnly 
                value={generatedLink} 
                className="flex-1 bg-slate-800 border-none rounded-xl px-4 py-3 text-sm text-slate-300 font-mono"
              />
              <button 
                onClick={() => { navigator.clipboard.writeText(generatedLink); alert('Copied!'); }}
