};

const SubmissionTool = ({ prefill }: { prefill?: { buyer?: string, type?: string, period?: string } }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [extractedValue, setExtractedValue] = useState<number | ''>('');
  const [selectedType, setSelectedType] = useState<DataType>(prefill?.type && prefill.type !== 'ANY' ? prefill.type as DataType : DataType.ELECTRICITY);
  const [supplierName, setSupplierName] = useState('');
  const [notes, setNotes] = useState('');
  const [feedback, setFeedback] = useState<{msg: string, type: 'info' | 'warn' | 'error'} | null>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 10 * 1024 * 1024) {
      setFeedback({ msg: "File too large (>10MB).", type: 'error' });
      return;
    }

    setIsProcessing(true);
    setFeedback({ msg: "AI is processing your file...", type: 'info' });

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64Data = reader.result as string;
        const result = await extractDataFromDocument(base64Data, file.type || "image/jpeg");

        if (result && result.value !== null) {
          setExtractedValue(result.value);
          if (result.detectedDataType) setSelectedType(result.detectedDataType as DataType);
          if (result.supplierName) setSupplierName(result.supplierName);

          setFeedback({ 
            msg: `Extracted ${result.value} ${result.unit} from ${result.supplierName || 'document'}.`, 
            type: result.confidence < 0.8 ? 'warn' : 'info' 
          });
        } else {
          throw new Error("AI could not detect usage values.");
        }
      } catch (err: any) {
        setFeedback({ msg: err.message || "Extraction failed.", type: 'error' });
        setManualMode(true);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!supplierName || extractedValue === '') return alert("Supplier and value required.");
    const factor = EMISSION_FACTORS[selectedType];
    const submission: SubmissionData = {
      id: Math.random().toString(36).substring(2, 9),
      requestId: prefill?.buyer || 'INTERNAL',
      buyerName: prefill?.buyer || 'Direct Submission',
      activityValue: Number(extractedValue),
      unit: DATA_UNITS[selectedType],
      dataType: selectedType,
      emissionsKgCO2e: Number(extractedValue) * factor,
      emissionFactor: factor,
      notes: `${notes}${prefill?.period ? ` [Period: ${prefill.period}]` : ''}`,
      timestamp: Date.now(),
      fileName: supplierName
    };
    DB.saveSubmission(submission);
    setSubmitted(true);
  };

  if (submitted) return (
    <div className="max-w-md mx-auto py-24 px-4 text-center animate-in fade-in duration-500">
      <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-emerald-100">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
      </div>
      <h2 className="text-3xl font-black text-slate-900 tracking-tight">Data Submitted</h2>
      <p className="text-slate-500 mt-4 text-lg">Thank you. Your emissions data has been sent to {prefill?.buyer || 'the buyer'}.</p>
      <button onClick={() => window.location.hash = ''} className="mt-10 bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Done</button>
    </div>
  );

  const factor = EMISSION_FACTORS[selectedType];
  const unit = DATA_UNITS[selectedType];
  const calculatedEmissions = extractedValue !== '' ? (Number(extractedValue) * factor).toFixed(2) : '0.00';

  return (
    <div className="max-w-3xl mx-auto py-12 px-4">
      <div className="mb-10 text-center">
        {prefill?.buyer ? (
          <>
            <h1 className="text-4xl font-black text-slate-900 tracking-tight">Request from {prefill.buyer}</h1>
            <p className="text-slate-500 mt-2 text-lg font-medium">Reporting Period: <span className="text-indigo-600">{prefill.period || 'Not Specified'}</span></p>
          </>
        ) : (
          <>
            <h1 className="text-4xl font-black text-slate-900 tracking-tight">Supplier Submission</h1>
            <p className="text-slate-500 mt-2 text-lg font-medium">Upload your bills to automatically calculate emissions.</p>
          </>
        )}
      </div>

      <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200 border border-slate-100 overflow-hidden">
        <div className="p-8 bg-slate-900 text-white flex justify-between items-center">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <svg className="w-6 h-6 text-indigo-400" fill="currentColor" viewBox="0 0 20 20"><path d="M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3zM6 8a2 2 0 11-4 0 2 2 0 014 0zM16 18v-3a5.972 5.972 0 00-.75-2.906A3.005 3.005 0 0119 15v3h-3zM4.75 12.094A5.973 5.973 0 004 15v3H1v-3a3 3 0 013.75-2.906z"></path></svg>
            Extraction Engine
          </h2>
          {(extractedValue !== '' || manualMode) && (
            <button onClick={() => { setExtractedValue(''); setManualMode(false); setFeedback(null); }} className="text-xs font-bold text-indigo-400">Reset</button>
          )}
        </div>

        <div className="p-8 space-y-8">
          {!manualMode && !extractedValue && (
            <div className={`relative border-3 border-dashed rounded-3xl p-16 text-center transition-all ${isProcessing ? 'border-indigo-400 bg-indigo-50/50' : 'border-slate-200 hover:border-indigo-400 hover:bg-slate-50'}`}>
              {isProcessing ? (
                <div className="flex flex-col items-center gap-6 py-8">
                  <div className="animate-spin rounded-full h-14 w-14 border-t-4 border-indigo-600 border-r-4 border-r-transparent"></div>
                  <p className="text-indigo-600 font-black text-lg animate-pulse">Reading Document...</p>
                </div>
              ) : (
                <>
                  <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileUpload} accept="image/*,application/pdf" />
                  <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path></svg>
                  </div>
                  <p className="text-2xl font-black text-slate-800">Upload Data Source</p>
                  <p className="text-slate-500 mt-2 font-medium">PDF or Image (Bills, Receipts, Logs)</p>
                  <button className="mt-8 px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl text-sm shadow-xl">Select File</button>
                  <button onClick={() => setManualMode(true)} className="block w-full mt-8 text-slate-400 text-[10px] font-black uppercase tracking-widest">Skip to Manual</button>
                </>
              )}
            </div>
          )}

          {(extractedValue !== '' || manualMode) && (
            <div className="space-y-6 animate-in fade-in duration-500">
              {feedback && (
                <div className={`p-4 rounded-xl text-sm font-bold border-2 ${feedback.type === 'error' ? 'bg-red-50 text-red-900 border-red-100' : 'bg-emerald-50 text-emerald-900 border-emerald-100'}`}>
                  {feedback.msg}
                </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Supplier Name</label>
                  <input className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-bold" value={supplierName} onChange={(e) => setSupplierName(e.target.value)} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Category</label>
                  <select 
                    className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-bold"
                    value={selectedType}
                    onChange={(e) => setSelectedType(e.target.value as DataType)}
                    disabled={prefill?.type && prefill.type !== 'ANY'}
                  >
                    {Object.values(DataType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Quantity ({unit})</label>
                  <input type="number" className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50 px-5 py-4 font-black text-2xl" value={extractedValue} onChange={(e) => setExtractedValue(e.target.value === '' ? '' : parseFloat(e.target.value))} />
                </div>
              </div>
              <div className="bg-indigo-600 p-8 rounded-[2rem] text-white flex justify-between items-center">
                <div>
                  <p className="text-indigo-200 text-[10px] font-black uppercase mb-2">Calculated Emissions</p>
                  <p className="text-5xl font-black">{calculatedEmissions} <span className="text-lg opacity-60">kgCO₂e</span></p>
                </div>
                <div className="text-right text-[10px] font-black opacity-50">EF: {factor}</div>
              </div>
              <button onClick={handleSave} className="w-full bg-slate-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:scale-[1.02] transition-all">Submit to {prefill?.buyer || 'Buyer'}</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const HistoryPage = () => {
  const [submissions, setSubmissions] = useState<SubmissionData[]>([]);
  useEffect(() => { setSubmissions(DB.getSubmissions()); }, []);

  return (
    <div className="max-w-6xl mx-auto py-12 px-6">
      <h1 className="text-5xl font-black text-slate-900 tracking-tight mb-12">Submission History</h1>
      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        {submissions.length === 0 ? (
          <div className="p-32 text-center text-slate-400 font-bold">No history available.</div>
        ) : (
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-10 py-6">Buyer / Request</th>
                <th className="px-10 py-6">Supplier</th>
                <th className="px-10 py-6">Emissions</th>
                <th className="px-10 py-6 text-right">Date</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {submissions.map((sub) => (
                <tr key={sub.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-10 py-8 font-bold text-slate-900">{sub.buyerName}</td>
                  <td className="px-10 py-8 font-medium text-slate-500">{sub.fileName || 'Manual Entry'}</td>
                  <td className="px-10 py-8 font-black text-indigo-700 text-xl">{sub.emissionsKgCO2e.toFixed(1)} <span className="text-xs opacity-50">kg</span></td>
                  <td className="px-10 py-8 text-right text-slate-400 font-medium">{new Date(sub.timestamp).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [hash, setHash] = useState(window.location.hash);

  useEffect(() => {
    const handleHash = () => setHash(window.location.hash);
    window.addEventListener('hashchange', handleHash);
    return () => window.removeEventListener('hashchange', handleHash);
  }, []);

  // Simple Router
  const route = hash.split('?')[0];
  const params = new URLSearchParams(hash.split('?')[1] || '');

  const renderContent = () => {
    switch(route) {
      case '#create': return <CreateRequest />;
      case '#history': return <HistoryPage />;
      case '#submit': return <SubmissionTool prefill={{
        buyer: params.get('buyer') || undefined,
        type: params.get('type') || undefined,
        period: params.get('period') || undefined
      }} />;
      default: return <SubmissionTool />;
    }
  };

  return <Layout>{renderContent()}</Layout>;
}
